from pathlib import Path
import csv
import io
import json
import re
import subprocess

out = Path('evidence')
out.mkdir(exist_ok=True)
pdfs = {}
refs = {}
for p in sorted(Path('.').glob('*.pdf')):
    dest = out / (p.stem + '.txt')
    subprocess.run(['pdftotext', '-layout', str(p), str(dest)], check=True)
    # 改ページ文字で行を増やさず、LFだけで行番号を数える。
    lines = dest.read_text().split('\\n')
    i = [i for i, s in enumerate(lines) if '殺人（既遂）' in s][-1]
    years = [int(s) + 2018 for s in re.findall(r'令和\\s*([０-９0-9]+)\\s*年', lines[i-2])]
    if '平成' in lines[i-2]:
        years.insert(0, 2018)
    if '令和元年' in lines[i-2]:
        years.insert(1 if years[0] == 2018 else 0, 2019)
    rows = [[int(x) for x in re.findall(r'\\d+', lines[j])] for j in [i, i+1]]
    assert len(years) == len(rows[0]) == len(rows[1]) == 5
    pdfs[p.name] = {y: (a, b) for y, a, b in zip(years, *rows)}
    refs[p.name] = {'header': i-1, 'completed': i+1, 'attempted': i+2}

csvs = {}
for p in sorted(Path('.').glob('*_CA.csv')):
    raw = p.read_bytes()
    try:
        s = raw.decode('utf-8-sig')
        enc = 'utf-8-sig'
    except UnicodeDecodeError:
        s = raw.decode('cp932')
        enc = 'cp932'
    rows = list(csv.reader(io.StringIO(s)))
    years = []
    for s in rows[2][3:8]:
        if s == '平成30年': y = 2018
        elif s == '令和元年': y = 2019
        else: y = int(re.search(r'令和([０-９0-9]+)年', s)[1]) + 2018
        years.append(y)
    csvs[p.name] = {y: (int(a), int(b)) for y, a, b in zip(years, rows[4][3:8], rows[5][3:8])}
    assert csvs[p.name] == pdfs[p.name.replace('_CA.csv', '_資料.pdf')]

sums = {name: {y: sum(pair) for y, pair in table.items() if y in [2020, 2021]} for name, table in pdfs.items()}
shared = {}
for year in range(2022, 2026):
    entries = {name: table[year] for name, table in pdfs.items() if year in table}
    assert len(set(entries.values())) == 1
    shared[year] = entries
assert pdfs['R6_資料.pdf'][2024][0] == pdfs['R7_資料.pdf'][2024][0] == 32
assert csvs['R6_CA.csv'][2023][1] == 25
assert all(v == (78 if y == 2020 else 64) for t in sums.values() for y, v in t.items())
result = {'PDF': pdfs, 'PDF行参照': refs, 'CSV': csvs, '2020・2021年の既遂＋未遂': sums, '2022年以降の照合': shared}
(out / 'verification.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\\n')
print(json.dumps(result, ensure_ascii=False, indent=2))
PY
